package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Map;

import org.springframework.samples.petclinic.rest.escalation.InvalidPostcodeException;

/**
 * Postcode validation for pet owners. A postcode is optional; when present it must be a 4-digit
 * number. When the owner's city maps to a known region (see {@link Locality}) the postcode must
 * fall inside that region's fixed inclusive range: {@code NSW 2000-2099}, {@code VIC 3000-3099},
 * {@code QLD 4000-4099}. A city with no known region ({@code UNKNOWN}) accepts any 4-digit
 * postcode. Derived purely from the fixed region table, so it is seed-independent.
 */
public final class Postcode {

    /** Region -> inclusive 4-digit postcode range {low, high}. Fixed, pinned reference data. */
    private static final Map<String, int[]> REGION_RANGES = Map.of(
            "NSW", new int[] {2000, 2099},
            "VIC", new int[] {3000, 3099},
            "QLD", new int[] {4000, 4099});

    private Postcode() {
    }

    /**
     * Validates the supplied postcode for the given city. A {@code null} or blank postcode is
     * treated as absent and passes (postcode is optional). Otherwise it must be exactly 4 digits,
     * and when the city's region has a known range the postcode must be within it.
     *
     * @throws InvalidPostcodeException when the postcode is malformed or out of range for the
     * city's region.
     */
    public static void validate(String postcode, String city) throws InvalidPostcodeException {
        if (postcode == null || postcode.isBlank()) {
            return; // absent: optional
        }
        if (!postcode.matches("[0-9]{4}")) {
            throw new InvalidPostcodeException("Postcode must be 4 digits: " + postcode);
        }
        int[] range = REGION_RANGES.get(Locality.of(city));
        if (range == null) {
            return; // unknown region: any 4-digit postcode accepted
        }
        int value = Integer.parseInt(postcode);
        if (value < range[0] || value > range[1]) {
            throw new InvalidPostcodeException("Postcode " + postcode + " is not valid for city "
                    + city + " (expected " + range[0] + "-" + range[1] + ")");
        }
    }
}
===== Locality.java =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Map;

/**
 * Locality (canonical region) for pet owners. The region is resolved from the owner's postcode
 * first, using fixed inclusive postcode ranges: {@code NSW 2000-2099}, {@code VIC 3000-3099},
 * {@code QLD 4000-4099}. When the postcode is absent or falls in no known range, it falls back to
 * a fixed city-to-region table: {@code Sydney -> NSW}, {@code Melbourne -> VIC},
 * {@code Brisbane -> QLD}. Anything unresolved yields {@code UNKNOWN}. Preferring the postcode
 * returns the same region for known cities but disambiguates cities that share a name. Derived
 * purely from the owner's own state, so it carries no stored data and is seed-independent. Used by
 * the owner mapper to expose {@code locality} on responses.
 */
public final class Locality {

    /** City -> canonical region. Fixed, pinned reference data. */
    private static final Map<String, String> CITY_REGION = Map.of(
            "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");

    /** Region -> inclusive 4-digit postcode range {low, high}. Fixed, pinned reference data. */
    private static final Map<String, int[]> REGION_RANGES = Map.of(
            "NSW", new int[] {2000, 2099},
            "VIC", new int[] {3000, 3099},
            "QLD", new int[] {4000, 4099});

    private Locality() {
    }

    /**
     * The canonical region for the given owner, resolved from the postcode first and falling back
     * to the city when the postcode is absent or in no known range. Yields {@code UNKNOWN} when
     * neither resolves.
     */
    public static String of(String postcode, String city) {
        String byPostcode = fromPostcode(postcode);
        return byPostcode != null ? byPostcode : of(city);
    }

    /**
     * The canonical region for the given city, or {@code UNKNOWN} when the city is not in the
     * fixed table.
     */
    public static String of(String city) {
        return CITY_REGION.getOrDefault(city, "UNKNOWN");
    }

    /** The region whose range contains the postcode, or {@code null} when absent or out of range. */
    private static String fromPostcode(String postcode) {
        if (postcode == null || !postcode.matches("[0-9]{4}")) {
            return null;
        }
        int value = Integer.parseInt(postcode);
        for (Map.Entry<String, int[]> entry : REGION_RANGES.entrySet()) {
            int[] range = entry.getValue();
            if (value >= range[0] && value <= range[1]) {
                return entry.getKey();
            }
        }
        return null;
    }
}
===== OwnerIdentity.java =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Locale;

import org.springframework.samples.petclinic.rest.escalation.InvalidTelephoneException;

/**
 * The single derived identity of a pet owner, consolidating the former telephone, email and
 * household duplicate checks into one derived key. The {@code identityKey} is
 * {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}, where the telephone is
 * canonical E.164 form, the email is trimmed and lower-cased (or empty when absent) and the household
 * id is {@link Household#id(String, String)} over the last name and address.
 *
 * <p>Because the telephone is part of the key, two members of the same household (same householdId)
 * with different telephones have different identity keys and are both allowed; only owners that are
 * the same contact collide. Duplicate detection compares the {@link #contactKey(String, String)} —
 * the telephone-and-email prefix of the key that is what actually identifies one owner, so two owners
 * in the same household with different telephones (or emails) are distinct and both persist.
 *
 * <p>Used by {@link RequireUniqueIdentity} to reject a collision and by the owner mapper to expose
 * the full key on responses.
 */
public final class OwnerIdentity {

    private OwnerIdentity() {
    }

    /** The full identity key for an owner with the given raw fields, as exposed on responses. Fields
     *  are normalized here so the same value is produced whether they come from a freshly-validated
     *  request or a stored owner. */
    public static String key(String telephone, String email, String lastName, String address) {
        return contactKey(telephone, email) + "|" + Household.id(lastName, address);
    }

    /** The telephone-and-email prefix of the identity key, identifying a single contact. Two owners
     *  are duplicates when their contact keys are equal. */
    public static String contactKey(String telephone, String email) {
        return normalizeTelephone(telephone) + "|" + normalizeEmail(email);
    }

    private static String normalizeTelephone(String telephone) {
        try {
            return OwnerTelephone.toE164(telephone);
        }
        catch (InvalidTelephoneException ex) {
            return telephone == null ? "" : telephone;
        }
    }

    private static String normalizeEmail(String email) {
        if (email == null || email.isBlank()) {
            return "";
        }
        return email.trim().toLowerCase(Locale.ROOT);
    }
}
===== OwnerTelephone.java =====
package org.springframework.samples.petclinic.rest.function.owner;

import org.springframework.samples.petclinic.rest.escalation.InvalidTelephoneException;

/**
 * Shared normalization of an owner telephone to E.164 form. Spaces, dashes and brackets are
 * stripped. A leading {@code '+'} and its country code are kept as supplied; otherwise the default
 * country code {@code '+61'} is assumed and a single leading {@code '0'} is dropped from the
 * national digits. The result must carry 8 to 15 digits after the {@code '+'}, or the value is
 * rejected as invalid.
 *
 * <p>The national-number length is also checked against the country code: {@code '+61'} requires 9
 * national digits and {@code '+1'} requires 10. A wrong length for the country is rejected.
 *
 * <p>Examples: {@code "0412 345 678" -> "+61412345678"}, {@code "+64 21 123 456" -> "+6421123456"}.
 */
final class OwnerTelephone {

    private OwnerTelephone() {
    }

    /**
     * @return the canonical E.164 telephone (a {@code '+'} followed by 8-15 digits).
     * @throws InvalidTelephoneException when the value cannot form a valid E.164 number.
     */
    static String toE164(String telephone) throws InvalidTelephoneException {
        if (telephone == null) {
            throw invalid();
        }
        // Strip spaces, dashes and brackets; any other non-digit survives and fails the check below.
        String stripped = telephone.replaceAll("[\\s()\\-]", "");
        String e164;
        if (stripped.startsWith("+")) {
            e164 = "+" + stripped.substring(1);
        }
        else {
            String national = stripped;
            if (national.startsWith("0")) {
                national = national.substring(1);
            }
            e164 = "+61" + national;
        }
        String digits = e164.substring(1);
        if (!digits.matches("[0-9]{8,15}")) {
            throw invalid();
        }
        // Per-country national-number length. Only the country codes with a known fixed length are
        // enforced; others keep the generic 8-15 digit rule above.
        if (e164.startsWith("+61")) {
            requireNationalLength(e164, "+61", 9);
        }
        else if (e164.startsWith("+1")) {
            requireNationalLength(e164, "+1", 10);
        }
        return e164;
    }

    private static void requireNationalLength(String e164, String countryCode, int nationalDigits)
            throws InvalidTelephoneException {
        // e164 is '+' + all digits; drop the leading '+' and the country code to get the national part.
        int national = e164.length() - 1 - (countryCode.length() - 1);
        if (national != nationalDigits) {
            throw new InvalidTelephoneException("Telephone with country code " + countryCode
                    + " must have " + nationalDigits + " national digits");
        }
    }

    private static InvalidTelephoneException invalid() {
        return new InvalidTelephoneException(
                "Telephone must form a valid E.164 number with 8 to 15 digits after the country code");
    }
}
===== RequireUniqueIdentity.java =====
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.DuplicateIdentityException;

/**
 * Step of {@code POST /api/owners} that rejects a create whose derived identity (see
 * {@link OwnerIdentity}) collides with an existing owner's, throwing {@link DuplicateIdentityException}
 * (handled as 409 Conflict). This is the single, consolidated duplicate check that replaces the
 * former separate telephone, email and household checks: they are all expressed through the one
 * {@code identityKey}. Because the telephone is part of the key, two members of the same household
 * (same householdId) with different telephones are distinct contacts and are both allowed; only two
 * owners that are the same contact (matching telephone and email) collide.
 *
 * <p>Runs after {@link RequireOwnerFields} has normalized and published the body and before
 * {@link BuildOwner}/{@link SaveOwner} persist the new owner.
 */
public class RequireUniqueIdentity {

    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
            throws DuplicateIdentityException {
        String contactKey = OwnerIdentity.contactKey(request.getTelephone(), request.getEmail());
        for (Owner existing : ownerRepository.findAll()) {
            String existingKey = OwnerIdentity.contactKey(existing.getTelephone(), existing.getEmail());
            if (contactKey.equals(existingKey)) {
                throw new DuplicateIdentityException(
                        "An owner with the same identity already exists");
            }
        }
    }
}

